/**
 * 多来源水质混配业务服务。
 *
 * <p>受理：加权指标 = Σ(来源体积 × 来源指标) / Σ来源体积，总体积不得为零；
 * 任一来源额度不足、指标缺失或加权结果超过用途阈值，整单 422 回滚，不扣任何来源额度；
 * 等于阈值可受理。所有来源配额在一次事务内按固定顺序锁定后预占。</p>
 *
 * <p>幂等：同一 requestId 同来源同体积重放首次配额与计算结果；改来源或体积返回 409。
 * 取消释放原预占量，历史体积、指标与加权值保留不重算。</p>
 */
@Service
public class BlendService {

    static final String STATUS_RESERVED = "RESERVED";
    static final String STATUS_CANCELLED = "CANCELLED";

    private final BlendRepository repository;
    private final TransactionTemplate tx;

